--
-- Name: users; Type: TABLE; Schema: public; Owner: -
-- Purpose: Authentication — stores login credentials and role for each user
--

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS public.users (
    user_id       SERIAL PRIMARY KEY,
    employee_id   INTEGER REFERENCES public.employees(employee_id) ON DELETE SET NULL,
    email         VARCHAR(255) UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role          VARCHAR(50) NOT NULL DEFAULT 'staff',
    -- role values: 'admin' | 'hr' | 'staff'
    is_active     BOOLEAN NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    last_login    TIMESTAMP WITHOUT TIME ZONE
);

COMMENT ON TABLE public.users IS 'Authentication table — stores hashed passwords and roles. Join with employees on email for full profile.';
COMMENT ON COLUMN public.users.role IS 'Access level: admin (full access), hr (user management + all HR), staff (self-service only)';

--
-- Seed demo / initial accounts
-- Passwords are bcrypt-hashed via pgcrypto crypt()
--

INSERT INTO public.users (email, password_hash, role) VALUES
  ('aimanhakimka@gmail.com', crypt('aiman123',   gen_salt('bf')), 'admin'),
  ('admin@chinhin.com',      crypt('Admin@123',  gen_salt('bf')), 'admin'),
  ('hr@chinhin.com',         crypt('HR@2026',    gen_salt('bf')), 'hr'),
  ('staff@chinhin.com',      crypt('Staff@2026', gen_salt('bf')), 'staff')
ON CONFLICT (email) DO NOTHING;

--
-- Login query (for reference / n8n node)
-- Replace $1 with the input email and $2 with the input plain-text password
--
-- SELECT
--     u.user_id,
--     u.email,
--     u.role,
--     u.is_active,
--     e.employee_name  AS name,
--     e.employee_id,
--     e.phone_number
-- FROM public.users u
-- LEFT JOIN public.employees e ON e.email = u.email
-- WHERE u.email = $1
--   AND u.password_hash = crypt($2, u.password_hash)
--   AND u.is_active = TRUE;

--
-- Register new user (for n8n node)
-- INSERT INTO public.users (email, password_hash, role)
-- VALUES ($1, crypt($2, gen_salt('bf')), $3)
-- ON CONFLICT (email) DO NOTHING
-- RETURNING user_id, email, role;

--
-- Update user (change password / role / email / active)
